151	              <SelectValue />
152	            </SelectTrigger>
153	            <SelectContent>
154	              {STATUS_OPTIONS.map((s) => (
155	                <SelectItem key={s} value={s}>
156	                  {statusLabel[s]}
157	                </SelectItem>
158	              ))}
159	            </SelectContent>
160	          </Select>
161	        </div>
162	
163	        {/* Priority */}
